import{z as A,x as p,o as r,c as d,q as i,j as n,D as e,d as l,s,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"杂散光与 flare","description":"","frontmatter":{"title":"杂散光与 flare","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/flare-and-stray.md","filePath":"litho/flare-and-stray.md","lastUpdated":1791413859000}'),f={name:"litho/flare-and-stray.md"};function m(h,a,B,D,C,c){const E=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="杂散光与-flare" tabindex="-1">杂散光与 flare <a class="header-anchor" href="#杂散光与-flare" aria-label="Permalink to &quot;杂散光与 flare&quot;">​</a></h1><div class="epigraph"><p>Flare 是不该参与成像的光：散射与杂散把一份缓变底座加进空中像，暗区变亮，全场对比随图形密度而变。</p><footer>—— 据 Mack、Levinson 对 flare 的定义；EUV 多层膜粗糙散射见 Bakshi 的公开论述</footer></div><p><a href="/litho/yieldstar-dbo">上一课</a>（YieldStar 与扫描仪内计量）。在此之上，位置计量钉在标记上。缺口是剂量底座：镜头、腔体与掩模的散射并不进「理想 TCC」，却给 \\(I(x,y)\\) 加上长程背景，使上一课程定义的对比度 \\(C\\) 在全场尺度上下降。本课钉 flare。flare 底座不进模拟会漏掉什么，下一课钉<a href="/litho/hotspot-pv">热点与过程变化</a>；水作介质抬 \\(\\mathrm{NA}\\)，是计量课程之后 DUV 课的起点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空中像课的 \\(C\\) 是局部、理想光学的。真实物镜有表面粗糙、镀膜缺陷、机械结构的反射，EUV 多层膜还有带内散射。一部分光离开设计的衍射级，以大范围晕斑落在晶圆上。暗区 \\(I_\\mathrm{min}\\) 被抬高，NILS 掉，E–D 窗口按图形密度缩——开阔区周围的密图形和密区里的孤立暗线，吃到的底座不同。</p><p><span class="marginnote">直觉类比：flare 就像漆黑房间里看一块屏幕，画面四周总有一层灰蒙蒙的光晕——它不属于画面内容，是环境光被各种表面弹进你眼睛的。光刻里这层「灰底」落在本该纯黑的暗区上，把黑变成了深灰，黑白的分辨力（对比度）自然就掉了。</span></p><p>缺口因此是给这层底座一个名字和尺度，而不是再设计一套套刻垫。没有 flare，OPC 会把「开阔区 CD 偏大」修到掩模上，根子却在长程散射。</p><h3 id="kirk-测试量的是总底座" tabindex="-1">Kirk 测试量的是总底座 <a class="header-anchor" href="#kirk-测试量的是总底座" aria-label="Permalink to &quot;Kirk 测试量的是总底座&quot;">​</a></h3><p>经典 Kirk flare：在大暗区里开不同尺寸的亮垫（或反过来），看多大的暗区仍能被胶打印，从而估散射到该点的背景比例。它给出一个积分量，不自动给出点扩散的长尾形状。产线还要区分局部 flare（几十到几百微米）与全场/腔体杂散。</p><p><span class="marginnote">Kirk 测试可以翻译成「给镜头漏光做体检」：在掩模上挖一大块全黑、里面留一小簇亮点，然后看这簇亮点还能不能被显影打印出来。亮点越小还能打印，说明黑区漏光越少、flare 越低。它量的是总底座这个体检指标，不能直接给出散射在空间上怎么分布。</span></p><p><span class="marginnote">EUV 的 flare 往往比浸没 DUV 更疼：多层膜中频粗糙把可观能量打进散射，公开讨论里总 flare 可到几个百分点量级，且随空间频率分。具体机台数字用厂商公开值，不编造。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模把 flare 写成对空中像的长程卷积，或加一个与开孔率成正比的 DC 项再加中程核。OPC 必须吃进开孔率依赖：同一条线在 10% 与 70% 开孔率下有效剂量不同。补偿是局部剂量调整或掩模偏置，不能靠把 \\(\\gamma\\) 做陡来「切掉」DC——底座抬的是 \\(I_\\mathrm{min}\\)，陡胶仍然看见被抬高的暗区。</p><p><span class="marginnote">常见误区：初学者容易以为把光刻胶衬度做陡就能「切掉」flare。实际上底座抬高的是暗区的绝对光强，胶再陡也只是把灰阶更干脆地判成黑或白，判不掉已经多出来的那部分光子。出路只有两条：从源头少产生散射，或者按开孔率补剂量。</span></p><p>清洁、镀膜、光阑和腔体黑化减 DUV 杂散；EUV 还靠多层膜中频粗糙规格、光阑与真空腔设计。Pellicle 挡的是颗粒，不是镜面散射。</p><h3 id="与部分相干的区别" tabindex="-1">与部分相干的区别 <a class="header-anchor" href="#与部分相干的区别" aria-label="Permalink to &quot;与部分相干的区别&quot;">​</a></h3><p>\\(\\sigma\\) 描述的是故意引入的照明光瞳填充，TCC 已经包含。Flare 是设计光路之外的能量再分配，通常不进标称 TCC，要另加。不要把「\\(\\sigma\\) 太大对比差」和「flare 抬 \\(I_\\mathrm{min}\\)」写成同一个旋钮。</p>',17)),(r(),n(o,null,{default:e(()=>[s(E,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDEAL%5B%22%E7%90%86%E6%83%B3%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%20--%3E%20ADD%5B%22%E5%8A%A0%E9%95%BF%E7%A8%8B%E6%95%A3%E5%B0%84%E5%BA%95%E5%BA%A7%22%5D%0A%20%20ROUGH%5B%22%E8%A1%A8%E9%9D%A2%20%2F%20%E5%A4%9A%E5%B1%82%E8%86%9C%E7%B2%97%E7%B3%99%22%5D%20--%3E%20ADD%0A%20%20ADD%20--%3E%20C%5B%22%E5%85%A8%E5%9C%BA%20C%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20DENS%5B%22%E5%BC%80%E5%AD%94%E7%8E%87%22%5D%20--%3E%20ADD%0A%20%20C%20--%3E%20PW%5B%22E%E2%80%93D%20%E7%AA%97%E5%8F%A3%E9%9A%8F%E5%AF%86%E5%BA%A6%E5%8F%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"短程散射（几微米内）有时与镜头像差难分，表现像对比损失。长程 flare 让晶圆上一点看见整场开孔率的加权和：亮场给暗图形漏光，等效剂量增加、CD 按衬度曲线移动。扫描狭缝积分会把狭缝外的杂散也扫进来，时间上仍是底座。",-1)),(r(),n(o,null,{default:e(()=>[s(E,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20OPEN%5B%22%E5%85%A8%E5%9C%BA%E4%BA%AE%E5%8C%BA%EF%BC%88%E5%BC%80%E5%AD%94%E7%8E%87%E9%AB%98%EF%BC%89%22%5D%20--%3E%20SCAT%5B%22%E9%95%9C%E9%9D%A2%20%2F%20%E8%85%94%E4%BD%93%E6%95%A3%E5%B0%84%22%5D%0A%20%20SCAT%20--%3E%20BASE%5B%22%E9%95%BF%E7%A8%8B%E5%BA%95%E5%BA%A7%20%CE%94I%22%5D%0A%20%20DESIGN%5B%22%E6%9C%AC%E7%82%B9%E8%AE%BE%E8%AE%A1%E6%88%90%E5%83%8F%EF%BC%9A%E6%9A%97%E5%8C%BA%E5%BA%94%E6%8E%A5%E8%BF%91%200%22%5D%20--%3E%20IMIN%5B%22%E5%AE%9E%E9%99%85%20I_min%22%5D%0A%20%20BASE%20--%3E%20IMIN%0A%20%20IMIN%20--%3E%20NILS%5B%22NILS%20%E4%B8%8E%20C%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20NILS%20--%3E%20EDW%5B%22E%E2%80%93D%20%E7%AA%97%E5%8F%A3%E5%8F%98%E7%AA%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>这张图回答的问题是：flare 如何一步步把「窗口变窄」这个最终后果造出来。散射底座把本该接近零的暗区光强抬到 \\(\\Delta I + I_\\mathrm{min}\\)，对比度、NILS、窗口面积沿同一条因果链缩水，且 \\(\\Delta I\\) 随全场开孔率变化。</p><p>套刻标记的对比也会被 flare 稀释，但位移偏置不是 flare 的一阶效应；一阶是 CD 与窗口。把 overlay 漂移全写到 flare 上，会修错。</p><h3 id="暗场掩模从源头减底座" tabindex="-1">暗场掩模从源头减底座 <a class="header-anchor" href="#暗场掩模从源头减底座" aria-label="Permalink to &quot;暗场掩模从源头减底座&quot;">​</a></h3><p>版图与掩模类型决定开孔率。暗场（尽量少透光）让长程积分变小，这是设计规则与 att-PSM / 二元选择的接口，不是镜头镀膜能单独买到的。剂量补偿按局部透光率加减，只能扳回平均 CD，扳不回已经损失的 \\(C\\)。元件 TIS（总积分散射）是镜子合同，整机 flare 还含腔体与掩模，不能用一张镜子的 TIS 代替 Kirk 测试。</p><p><span class="marginnote">浸没水层的气泡、水印是流体缺陷，不是本课的镜头 flare。CD、套刻、剂量底座三张尺子已点名；热点与过程变化留给下一课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把某代 NXE 的 flare 百分比写成普适常数。也不讨论鬼像的每一个机械来源。浸没水中的气泡与颗粒散射是另一类缺陷，不要并进镜头 flare 规格。后课默认：说到对比度，量产还要问开孔率与 flare 模型是否在 OPC 里。</p><p>成像与胶的主干在本课程收尾处还剩热点、刻蚀偏置与显影后检验几笔；下一个课程从 ArF 浸没的介质 \\(n\\) 重新加一档 \\(\\mathrm{NA}\\)。镜头像差（球差、彗差）是设计波前，不是 flare；两者都会掉 NILS，修正手段不同——一个靠透镜与照明，一个靠散射控制与密度补偿。</p><p><span class="marginnote">全场开孔率随产品而变。存储器阵列几乎匀，逻辑后段疏密差大，flare 指纹更毒。同一台镜头、不同产品，有效 \\(C\\) 可以不是同一个数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Flare 是长程杂散底座，抬 \\(I_\\mathrm{min}\\)，对比随开孔率变。</li><li>Kirk 一类测试给积分量；OPC 需要有空间核的模型。</li><li>陡胶切不掉 DC；要减散射或按密度补偿剂量。</li><li>\\(\\sigma\\) 是故意的部分相干，flare 不是。</li><li>计量课程还剩热点与验收；浸没 DUV 在下一个课程。</li><li>出处：Mack / Levinson 对 flare 的讨论；Bakshi, <em>EUV Lithography</em> 对多层膜散射。</li></ul>',11))])}const u=A(f,[["render",m]]);export{I as __pageData,u as default};
